test("要素がある並びは、同じ要素を同じ順に持つ空でない並びになる", () => {
  expect(ArrayEx.toNonEmpty(["b", "a", "c"])).toEqual(
    Option.some(["b", "a", "c"]),
  );
});

test("空の並びは空でない並びにならない", () => {
  expect(ArrayEx.toNonEmpty([])).toEqual(Option.none);
});

test("祖先と子孫を指すと祖先だけが残る", () => {
  expect(outermostNamesOf(["card", "caption"])).toEqual(Option.some(["card"]));
});

test("互いに関係の無いノードは指した順に並ぶ", () => {
  expect(outermostNamesOf(["footer", "title"])).toEqual(
    Option.some(["footer", "title"]),
  );
});

test("同じ名前を 2 回指しても 1 つになる", () => {
  expect(outermostNamesOf(["title", "title"])).toEqual(Option.some(["title"]));
});

test("artboard と別のノードを指すと最上位のノードは無い", () => {
  expect(outermostNamesOf(["about", "title"])).toEqual(Option.none);
});

test("何も指さなければ最上位のノードは無い", () => {
  expect(outermostNamesOf([])).toEqual(Option.none);
});

test("兄弟を 2 つ指すと、それぞれの直後に複製が入る", () => {
  expect(screenChildNamesAfterCopying(["title", "card"])).toEqual([
    "title",
    "title-2",
    "card",
    "card-2",
    "login",
    "footer",
  ]);
});

test("別の artboard のノードを指すと、それぞれの親の中の直後に複製が入る", () => {
  const { document } = Option.unwrap(
    DesignDocument.insertCopiesAfter(documentWithChildInEachArtboard(), [
      "about-title",
      "home-title",
    ]),
  );

  expect(
    document.artboards.map((artboard) =>
      artboard.children.map((child) => child.name),
    ),
  ).toEqual([
    ["home-title", "home-title-2"],
    ["about-title", "about-title-2"],
  ]);
});

test("複製の名前は、指した順に並ぶ", () => {
  const { copyNames } = Option.unwrap(
    DesignDocument.insertCopiesAfter(copySourceDocument(), ["footer", "title"]),
  );

  expect(copyNames).toEqual(["footer-2", "title-2"]);
});

/**
 * `title` を一度複製して `title-2` を作ったうえで、`title` と `title-2` をまとめて複製する。
 *
 * @returns 2 度目の複製の結果
 */
function copyOriginalAndItsCopy(): InsertedCopies {
  const { document } = Option.unwrap(
    DesignDocument.insertCopiesAfter(copySourceDocument(), ["title"]),
  );
  return Option.unwrap(
    DesignDocument.insertCopiesAfter(document, ["title", "title-2"]),
  );
}

test("まとめて複製すると、先に作った複製の名前を避けて次の連番が付く", () => {
  expect(copyOriginalAndItsCopy().copyNames).toEqual(["title-3", "title-4"]);
});

test("まとめて複製しても、ドキュメントの名前は重ならない", () => {
  const duplicateNameErrors = DesignDocument.collectErrors(
    copyOriginalAndItsCopy().document,
  ).filter((error) => error.kind === "duplicate-name");

  expect(duplicateNameErrors).toEqual([]);
});

test("artboard が混ざると複製できない", () => {
  expect(
    DesignDocument.insertCopiesAfter(documentWithChildInEachArtboard(), [
      "home",
      "about-title",
    ]),
  ).toEqual(Option.none);
});

test("指した位置から、渡した順に複製が並ぶ", () => {
  const inserted = Result.unwrap(
    DesignDocument.insertNodeCopies(
      setupDocument(),
      { parentName: "screen", index: 1 },
      [
        { name: "zeta", type: "Text" },
        { name: "alpha", type: "Text" },
      ],
    ),
  );

  expect(inserted.artboards[0].children.map((child) => child.name)).toEqual([
    "label",
    "zeta",
    "alpha",
    "footer",
  ]);
});

test("同じ名前のノードを 2 つ渡しても、複製どうしともドキュメントとも名前が重ならない", () => {
  const inserted = Result.unwrap(
    DesignDocument.insertNodeCopies(
      setupDocument(),
      { parentName: "screen", index: 1 },
      [
        { name: "label", type: "Text" },
        { name: "label", type: "Text" },
      ],
    ),
  );

  expect(DesignDocument.collectErrors(inserted)).toEqual([]);
});

test("空の並びは型で渡せない", () => {
  expectTypeOf<readonly []>().not.toExtend<
    Parameters<typeof DesignDocument.insertNodeCopies>[2]
  >();
});

test("複数選んでコピーすると、選んだ順にクリップボードへ入る", () => {
  const copied = copyNodes(["sibling-panel", "outer-panel"]);

  expect(copiedNamesOf(copied)).toEqual(
    Option.some(["sibling-panel", "outer-panel"]),
  );
});

test("親と子を選んでコピーすると、親のサブツリーだけが入る", () => {
  const copied = copyNodes(["inner-panel", "outer-panel"]);

  expect(copiedNamesOf(copied)).toEqual(Option.some(["outer-panel"]));
});

test("1 つだけ選んで貼ると、写した順に末尾へ全部並ぶ", () => {
  expect(childNames(pasteIntoSiblingPanel(), "sibling-panel")).toEqual([
    "home-login-2",
    "outer-panel-2",
  ]);
});

test("まとめて貼ったものは 1 回の取り消しで全部戻る", () => {
  const undone = Option.unwrap(EditorState.undo(pasteIntoSiblingPanel()));

  expect(childNames(undone, "sibling-panel")).toEqual([]);
});

test("兄弟をまとめて複製すると、それぞれの直後に並ぶ", () => {
  expect(childNames(duplicateSiblings(), "home")).toEqual([
    "outer-panel",
    "outer-panel-2",
    "sibling-panel",
    "sibling-panel-2",
    "home-login",
  ]);
});

test("まとめて複製すると、複製がまとめて選ばれる", () => {
  expect(
    DocumentSelection.names(EditorState.documentSelection(duplicateSiblings())),
  ).toEqual(["sibling-panel-2", "outer-panel-2"]);
});

test("まとめて複製したものは 1 回の取り消しで全部戻る", () => {
  const undone = Option.unwrap(EditorState.undo(duplicateSiblings()));

  expect(childNames(undone, "home")).toEqual([
    "outer-panel",
    "sibling-panel",
    "home-login",
  ]);
});

test("複数選んでいる間は貼れない", () => {
  const copied = Option.unwrap(
    EditorState.copySelected(EditorState.select(setupState(), "home-badge")),
  );
  // 選択の並び順の先頭の home-panel は子を持てるので、先頭へ貼る実装ならここで貼れてしまう
  const multi = EditorState.selectNodes(copied, ["home-panel", "home-login"]);
  const single = EditorState.select(copied, "home-panel");

  expect(Option.isSome(EditorState.pasteCopied(single))).toBe(true);
  expect(Option.isSome(EditorState.pasteCopied(multi))).toBe(false);
});

test("同じ親の兄弟を複数選んでいるときは、複製・コピー・動かせる向きの並べ替え・削除が押せる", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(setupState(), ["title", "panel"]),
    EditMenuTargets.Node,
  );

  expect(enabledOperations(menu)).toEqual([
    EditOperations.Duplicate,
    EditOperations.Copy,
    EditOperations.BringForward,
    EditOperations.Delete,
  ]);
});

test("まとめて選んで Ctrl+D を押すと、それぞれの直後に複製が並ぶ", async () => {
  await renderWithSameComponentInstancesSelected();

  await userEvent.keyboard("{Control>}d{/Control}");

  expect(rowNames(tree())).toEqual([
    "home-title",
    "home-login",
    "home-login-2",
    "home-signup",
    "home-signup-2",
  ]);
});

test("まとめて選んで Ctrl+C を押し、artboard を選んで Ctrl+V を押すと、2 つとも末尾に並ぶ", async () => {
  await renderWithSameComponentInstancesSelected();
  await userEvent.keyboard("{Control>}c{/Control}");

  await selectArtboard("home");
  await userEvent.keyboard("{Control>}v{/Control}");

  expect(rowNames(tree())).toEqual([
    "home-title",
    "home-login",
    "home-signup",
    "home-login-2",
    "home-signup-2",
  ]);
});

test("まとめて選んだまま Ctrl+V を押しても、ツリーは変わらない", async () => {
  await renderOpenedDocument(SampleDocumentWithSameComponentInstances);
  await selectInTree("home-title");
  await userEvent.keyboard("{Control>}c{/Control}");
  await selectSameComponentInstances();

  await userEvent.keyboard("{Control>}v{/Control}");

  expect(rowNames(tree())).toEqual(["home-title", "home-login", "home-signup"]);
});

test("複数選択の一員の行のメニューの Duplicate を押すと、それぞれの直後に複製が並ぶ", async () => {
  await renderWithSameComponentInstancesSelected();

  rightClickInTree("home-signup");
  await userEvent.click(menuRow("Duplicate"));

  expect(rowNames(tree())).toEqual([
    "home-title",
    "home-login",
    "home-login-2",
    "home-signup",
    "home-signup-2",
  ]);
});

test("親が違うノードはすべて残る", () => {
  expect(outermostNamesOf(["caption", "about-title"])).toEqual(
    Option.some(["caption", "about-title"]),
  );
});

test("まとめて貼っても選択は動かない", () => {
  expect(EditorState.singleName(pasteIntoSiblingPanel())).toEqual(
    Option.some("sibling-panel"),
  );
});

test("親と子をまとめて選んで複製すると、親だけが複製される", () => {
  const duplicated = Option.unwrap(
    EditorState.duplicateSelected(
      EditorState.selectNodes(stateWithDeepBranch(), [
        "inner-panel",
        "outer-panel",
      ]),
    ),
  );

  expect(
    DocumentSelection.names(EditorState.documentSelection(duplicated)),
  ).toEqual(["outer-panel-2"]);
});

test("まとめて複製してもクリップボードの中身は変わらない", () => {
  const copied = Option.unwrap(
    EditorState.copySelected(
      EditorState.select(stateWithDeepBranch(), "home-login"),
    ),
  );

  const duplicated = Option.unwrap(
    EditorState.duplicateSelected(
      EditorState.selectNodes(copied, ["sibling-panel", "outer-panel"]),
    ),
  );

  expect(duplicated.copiedNodes).toEqual(
    Option.some([nodeNamed(copied, "home-login")]),
  );
});

toNonEmpty<T>(array: readonly T[]): Option<NonEmptyArray<T>> {
  if (array.length === 0) {
    return Option.none;
  }
  const [first, ...rest] = array;
  const nonEmpty: NonEmptyArray<T> = [first, ...rest];
  return Option.some(nonEmpty);
},

test("空の並びは型で渡せない", () => {
  expectTypeOf<readonly []>().not.toExtend<
    Parameters<typeof DesignDocument.insertNodeCopies>[2]
  >();
});

/**
 * 名前で指したものの最上位のノード（docs/06-ui.md「複数選択」のコピーと複製の対象）。
 *
 * artboard が 1 つでも混ざったら全体を `none` にする。一部だけ写すと貼るまで足りないことに
 * 気づけないので、複数選択の削除と同じく全部か無かにする。
 *
 * @param document 引き先になるドキュメント
 * @param names 指したものの名前。祖先が同じ並びにある名前は落とし、重複は 1 つとして扱う
 * @returns 最上位に残った名前のノードを、渡された順のまま並べたもの。空の並び・最上位に
 *   artboard の名前・部品定義の中のノードの名前・無い名前が入るときは `none`
 */
findOutermostNodes(
  document: DesignDocument,
  names: readonly string[],
): Option<NonEmptyArray<Node>> {
  const outermost = outermostNames(document, names);
  const nodes = outermost.flatMap((name) => {
    const node = DesignDocument.findNode(document, name);
    return Option.isSome(node) ? [node.value] : [];
  });
  return nodes.length === outermost.length
    ? ArrayEx.toNonEmpty(nodes)
    : Option.none;
},

insertCopiesAfter(
  document: DesignDocument,
  names: readonly string[],
): Option<InsertedCopies> {
  const nodes = DesignDocument.findOutermostNodes(document, names);
  if (!Option.isSome(nodes)) {
    return Option.none;
  }
  const initial: InsertedCopies = { document, copyNames: [] };
  // 見つかったノードだけを指すので `insertCopyAfter` は err にならない
  const inserted = ArrayEx.reduceUntilErr(
    nodes.value,
    initial,
    (current, node) =>
      Result.map(insertCopyAfter(current.document, node.name), (copy) => ({
        document: copy.document,
        copyNames: [...current.copyNames, copy.copyName],
      })),
  );
  return Interop.toOption(inserted);
},
